#!/usr/bin/env node

/**
 * Register ULS Component Demo in Main Navigation
 * 
 * Moves/copies custom-demo page to Pages/Documentation/UiComponents/
 * so it appears in the main navigation via auto-discovery.
 * 
 * Usage:
 *   npm run register-uls-component-demo UserCard
 *   node scripts/register-uls-component-demo.mjs UserCard
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// ==========================================================================
// UTILITY FUNCTIONS
// ==========================================================================

function generateComponentVariations(componentName) {
    const pascalCase = componentName.charAt(0).toUpperCase() + componentName.slice(1).replace(/-([a-z])/g, (g) => g[1].toUpperCase());
    const kebabCase = componentName.replace(/([A-Z])/g, '-$1').toLowerCase().replace(/^-/, '');
    
    return {
        ComponentName: pascalCase,
        componentName: pascalCase.charAt(0).toLowerCase() + pascalCase.slice(1),
        kebabName: kebabCase,
        routeBase: kebabCase
    };
}

function findProjectRoot() {
    // Start from current working directory (where user runs the command)
    let currentDir = process.cwd();
    
    // Go up to find project root (look for src/demo/uls-primereact or src/uls-components)
    while (currentDir !== path.dirname(currentDir)) {
        const demoPath = path.join(currentDir, 'src', 'demo', 'uls-primereact');
        const componentsPath = path.join(currentDir, 'src', 'uls-components');
        if (fs.existsSync(demoPath) || fs.existsSync(componentsPath)) {
            return currentDir;
        }
        currentDir = path.dirname(currentDir);
    }
    
    return null;
}

function findULSPackage() {
    // First try to find ULS repo (for when running from ULS_V2.0 itself)
    let currentDir = __dirname;
    
    while (currentDir !== path.dirname(currentDir)) {
        const primereactPath = path.join(currentDir, 'libs', 'uls-primereact');
        const ulsComponentsPath = path.join(currentDir, 'uls-components');
        if (fs.existsSync(primereactPath) && fs.existsSync(ulsComponentsPath)) {
            return currentDir;
        }
        currentDir = path.dirname(currentDir);
    }
    
    return null;
}

function findDemoAppPath() {
    // First, try to find project's demo app (src/demo/uls-primereact/src/)
    const projectRoot = findProjectRoot();
    if (projectRoot) {
        const projectDemoPath = path.join(projectRoot, 'src', 'demo', 'uls-primereact', 'src');
        if (fs.existsSync(projectDemoPath)) {
            return projectDemoPath;
        }
    }
    
    // Fallback: if running from ULS repo itself, use libs/uls-primereact/src
    const ulsRoot = findULSPackage();
    if (ulsRoot) {
        const ulsDemoPath = path.join(ulsRoot, 'libs', 'uls-primereact', 'src');
        if (fs.existsSync(ulsDemoPath)) {
            return ulsDemoPath;
        }
    }
    
    return null;
}

function copyFileSync(source, dest) {
    const destDir = path.dirname(dest);
    if (!fs.existsSync(destDir)) {
        fs.mkdirSync(destDir, { recursive: true });
    }
    fs.copyFileSync(source, dest);
}

function copyDirectorySync(source, dest) {
    if (!fs.existsSync(source)) {
        return false;
    }
    
    if (!fs.existsSync(dest)) {
        fs.mkdirSync(dest, { recursive: true });
    }
    
    const entries = fs.readdirSync(source, { withFileTypes: true });
    
    for (const entry of entries) {
        const sourcePath = path.join(source, entry.name);
        const destPath = path.join(dest, entry.name);
        
        if (entry.isDirectory()) {
            copyDirectorySync(sourcePath, destPath);
        } else {
            copyFileSync(sourcePath, destPath);
        }
    }
    
    return true;
}

// ==========================================================================
// COMPONENT TYPE DETECTION
// ==========================================================================

function isCustomComponent(componentName) {
    const projectRoot = findProjectRoot();
    const ulsRoot = findULSPackage();
    const kebabName = componentName.replace(/([A-Z])/g, '-$1').toLowerCase().replace(/^-/, '');
    
    // Check in project's custom-components folder
    if (projectRoot) {
        const customComponentPath = path.join(projectRoot, 'src', 'uls-components', 'src', 'custom-components', kebabName);
        const customComponentIndexPath = path.join(customComponentPath, 'index.js');
        const customComponentFile = path.join(customComponentPath, `${kebabName}.jsx`);
        
        if (fs.existsSync(customComponentIndexPath) || fs.existsSync(customComponentFile)) {
            return true;
        }
    }
    
    // Check in ULS repo's custom-components folder
    if (ulsRoot) {
        const ulsCustomComponentPath = path.join(ulsRoot, 'uls-components', 'src', 'custom-components', kebabName);
        const ulsCustomComponentIndexPath = path.join(ulsCustomComponentPath, 'index.js');
        const ulsCustomComponentFile = path.join(ulsCustomComponentPath, `${kebabName}.jsx`);
        
        if (fs.existsSync(ulsCustomComponentIndexPath) || fs.existsSync(ulsCustomComponentFile)) {
            return true;
        }
    }
    
    return false;
}

function isULSComponent(componentName) {
    const ulsRoot = findULSPackage();
    if (!ulsRoot) {
        return false;
    }
    
    const kebabName = componentName.replace(/([A-Z])/g, '-$1').toLowerCase().replace(/^-/, '');
    const componentPath = path.join(ulsRoot, 'uls-components', 'src', 'components', kebabName);
    const componentIndexPath = path.join(componentPath, 'index.js');
    const componentFile = path.join(componentPath, `${kebabName}.jsx`);
    
    return fs.existsSync(componentIndexPath) || fs.existsSync(componentFile);
}

async function createDemoPageIfNeeded(componentName) {
    const demoAppPath = findDemoAppPath();
    if (!demoAppPath) {
        throw new Error(
            'Demo app not found.\n' +
            'Expected: src/demo/uls-primereact/src/\n' +
            'Make sure you have run: npx uls init'
        );
    }
    
    const variations = generateComponentVariations(componentName);
    const pageFolderName = `${variations.ComponentName}Page`;
    const customDemoSourcePath = path.join(demoAppPath, 'custom-demo', pageFolderName);
    
    // If demo page already exists, skip creation
    if (fs.existsSync(customDemoSourcePath)) {
        return false; // Already exists, no need to create
    }
    
    // Determine which creation script to use
    let createScript;
    if (isCustomComponent(componentName)) {
        createScript = path.join(__dirname, 'create-custom-component-demo.mjs');
    } else if (isULSComponent(componentName)) {
        createScript = path.join(__dirname, 'create-uls-component-demo.mjs');
    } else {
        // Default to custom component creation (more common for user-created components)
        createScript = path.join(__dirname, 'create-custom-component-demo.mjs');
    }
    
    // Check if script exists
    if (!fs.existsSync(createScript)) {
        throw new Error(
            `Demo page creation script not found: ${createScript}\n` +
            `Please create the demo page manually using: npx uls create-custom-component-demo ${componentName}`
        );
    }
    
    console.log(`\n📦 Demo page not found. Creating it automatically...`);
    console.log(`   Component: ${variations.ComponentName}`);
    console.log(`   Using: ${path.basename(createScript)}\n`);
    
    // Use child_process to run the creation script
    const { spawn } = await import('child_process');
    
    return new Promise((resolve, reject) => {
        const child = spawn('node', [createScript, componentName], {
            stdio: 'inherit',
            cwd: process.cwd()
        });
        
        child.on('exit', (code) => {
            if (code === 0) {
                // Verify it was created
                if (fs.existsSync(customDemoSourcePath)) {
                    console.log(`\n✅ Demo page created successfully!\n`);
                    resolve(true);
                } else {
                    reject(new Error(`Demo page creation completed but file not found: ${customDemoSourcePath}`));
                }
            } else {
                reject(new Error(`Demo page creation failed with exit code ${code}`));
            }
        });
        
        child.on('error', (err) => {
            reject(new Error(`Failed to spawn demo page creation script: ${err.message}`));
        });
    });
}

// ==========================================================================
// REGISTRATION FUNCTION (Reusable)
// ==========================================================================

export async function registerComponentDemo(componentName, options = {}) {
    const { skipIfExists = false, silent = false, demoAppPath: providedDemoAppPath = null } = options;
    
    try {
        if (!componentName) {
            throw new Error('Component name is required');
        }
        
        const variations = generateComponentVariations(componentName);
        const pageFolderName = `${variations.ComponentName}Page`;
        
        // Find demo app path (project's src/demo/uls-primereact/src/ or ULS repo's libs/uls-primereact/src/)
        const demoAppPath = providedDemoAppPath || findDemoAppPath();
        if (!demoAppPath) {
            throw new Error(
                'Demo app not found.\n' +
                'Expected: src/demo/uls-primereact/src/\n' +
                'Make sure you have run: npx uls init'
            );
        }
        
        // Source: custom-demo folder
        const customDemoSourcePath = path.join(demoAppPath, 'custom-demo', pageFolderName);
        
        // Destination: Pages/Documentation/UiComponents folder (for auto-discovery)
        const uiComponentsPath = path.join(demoAppPath, 'Pages', 'Documentation', 'UiComponents');
        const destinationPath = path.join(uiComponentsPath, pageFolderName);
        
        // Check if custom-demo page exists, if not, create it automatically
        if (!fs.existsSync(customDemoSourcePath)) {
            console.log(`\n📦 Demo page not found. Creating it automatically...`);
            await createDemoPageIfNeeded(componentName);
            
            // Verify it was created
            if (!fs.existsSync(customDemoSourcePath)) {
                throw new Error(
                    `Demo page creation completed but file not found: ${customDemoSourcePath}\n` +
                    `Please create it manually using: npx uls create-custom-component-demo ${componentName}`
                );
            }
        }
        
        // Check if already registered
        if (fs.existsSync(destinationPath)) {
            if (skipIfExists) {
                console.log(`✓ Component "${variations.ComponentName}" is already registered. Skipping.`);
                return { success: true, skipped: true };
            }
            console.warn(`⚠️  Component "${variations.ComponentName}" is already registered in UiComponents.`);
            console.log(`   Location: ${destinationPath}`);
            console.log(`\n   To update, delete the existing folder and run this command again.`);
            return { success: false, error: 'Component already registered' };
        }
        
        // Copy custom-demo page to UiComponents
        console.log(`📦 Registering ${variations.ComponentName} in main navigation...`);
        console.log(`   Source: ${path.relative(process.cwd(), customDemoSourcePath)}`);
        console.log(`   Destination: ${path.relative(process.cwd(), destinationPath)}`);
        
        copyDirectorySync(customDemoSourcePath, destinationPath);
        
        // Ensure index.jsx exists and has correct import path (required for auto-discovery)
        const indexPath = path.join(destinationPath, 'index.jsx');
        let indexNeedsUpdate = false;
        let indexContent = '';
        
        if (fs.existsSync(indexPath)) {
            indexContent = fs.readFileSync(indexPath, 'utf8');
            // Check if import path needs to be fixed (from custom-demo path to UiComponents path)
            if (indexContent.includes("from '../../Components/Common/")) {
                indexContent = indexContent.replace(
                    /from\s+['"]\.\.\/\.\.\/Components\/Common\//g,
                    "from '../../../../Components/Common/"
                );
                indexNeedsUpdate = true;
            }
        } else {
            // Create new index.jsx with correct path
            indexContent = `import React from 'react';
import DocPageWrapper from '../../../../Components/Common/DocMain/DocPageWrapper';

export default function ${variations.ComponentName}Page() {
  return <DocPageWrapper componentName="${variations.componentName}" />;
}
`;
            indexNeedsUpdate = true;
        }
        
        if (indexNeedsUpdate) {
            fs.writeFileSync(indexPath, indexContent, 'utf8');
            console.log(`📝 ${fs.existsSync(indexPath) ? 'Updated' : 'Created'}: ${path.relative(process.cwd(), indexPath)}`);
        }
        
        // Update meta.js importMsg if needed (preserve user's category/subCategory)
        const metaPath = path.join(destinationPath, 'meta.js');
        if (fs.existsSync(metaPath)) {
            let metaContent = fs.readFileSync(metaPath, 'utf8');
            let updated = false;
            
            // Only update importMsg to use @uls/components (preserve category/subCategory from user input)
            if (!metaContent.includes("import {") || metaContent.includes("primereact/")) {
                metaContent = metaContent.replace(
                    /importMsg:\s*["']([^"']+)["']/,
                    `importMsg: "import { ${variations.ComponentName} } from '@uls/components'"`
                );
                updated = true;
            }
            
            if (updated) {
                fs.writeFileSync(metaPath, metaContent, 'utf8');
                console.log(`📝 Updated: ${path.relative(process.cwd(), metaPath)} (importMsg)`);
            }
        }
        
        // Fix import paths in features.jsx (update from custom-demo paths to UiComponents paths)
        const featuresPath = path.join(destinationPath, 'features.jsx');
        if (fs.existsSync(featuresPath)) {
            let featuresContent = fs.readFileSync(featuresPath, 'utf8');
            let updated = false;
            
            // Fix DocPanel, CodePreview, RichText imports (from ../../ to ../../../../)
            if (featuresContent.includes("from '../../Components/Common/")) {
                featuresContent = featuresContent.replace(
                    /from\s+['"]\.\.\/\.\.\/Components\/Common\//g,
                    "from '../../../../Components/Common/"
                );
                updated = true;
            }
            
            if (updated) {
                fs.writeFileSync(featuresPath, featuresContent, 'utf8');
                console.log(`📝 Updated: ${path.relative(process.cwd(), featuresPath)} (import paths)`);
            }
        }
        
        // Fix import paths in import.js (update custom-components path)
        const importPath = path.join(destinationPath, 'import.js');
        if (fs.existsSync(importPath)) {
            let importContent = fs.readFileSync(importPath, 'utf8');
            let updated = false;
            
            // Fix custom-components imports (from ../../ to ../../../../)
            if (importContent.includes("from '../../custom-components/")) {
                importContent = importContent.replace(
                    /from\s+['"]\.\.\/\.\.\/custom-components\//g,
                    "from '../../../../custom-components/"
                );
                updated = true;
            }
            
            if (updated) {
                fs.writeFileSync(importPath, importContent, 'utf8');
                console.log(`📝 Updated: ${path.relative(process.cwd(), importPath)} (import paths)`);
            }
        }
        
        // Read meta.js to get category for display
        let displayCategory = variations.ComponentName;
        const metaPathForDisplay = path.join(destinationPath, 'meta.js');
        if (fs.existsSync(metaPathForDisplay)) {
            try {
                const metaContent = fs.readFileSync(metaPathForDisplay, 'utf8');
                const categoryMatch = metaContent.match(/category:\s*['"]([^'"]+)['"]/);
                if (categoryMatch) {
                    displayCategory = categoryMatch[1];
                }
            } catch (err) {
                // Use default
            }
        }
        
        console.log(`\n✅ Successfully registered ${variations.ComponentName}!`);
        console.log(`\n📦 Component is now available in:`);
        console.log(`   Navigation: ${variations.ComponentName} (under ${displayCategory} category)`);
        console.log(`   Route: ${variations.routeBase}`);
        console.log(`\n💡 The component will appear in the demo app navigation automatically.`);
        console.log(`   No manual registration needed - auto-discovery handles it!`);
        
        return { success: true, path: destinationPath };
        
    } catch (error) {
        if (options.silent) {
            throw error;
        }
        console.error('\n❌ Error:', error.message);
        if (error.stack) {
            console.error('\nStack trace:', error.stack);
        }
        throw error;
    }
}

// ==========================================================================
// CLI FUNCTION (Standalone script)
// ==========================================================================

async function registerULSComponentDemo() {
    try {
        const args = process.argv.slice(2);
        const componentName = args[0];
        
        if (!componentName) {
            console.error('❌ Error: Component name is required');
            console.log('\nUsage:');
            console.log('  npm run register-uls-component-demo <ComponentName>');
            console.log('  node scripts/register-uls-component-demo.mjs <ComponentName>');
            console.log('\nExamples:');
            console.log('  npm run register-uls-component-demo UserCard');
            process.exit(1);
        }
        
        await registerComponentDemo(componentName);
    } catch (error) {
        console.error('\n❌ Error:', error.message);
        if (error.stack) {
            console.error('\nStack trace:', error.stack);
        }
        process.exit(1);
    }
}

// Run the registration if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
    registerULSComponentDemo();
}

